"use client";
import { EosSegmentedControl } from "@/components/application/eos/segmented-control";
import { EosTheme } from "@/components/application/eos/theme";

/** Installed or Discover, light and dark: the thumb slides to the choice. */
export default function EosSegmentedControlDemo() {
  return (
    <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 16 }}>
      <EosTheme mode="light" style={{ padding: 28, borderRadius: 24, border: "1px solid var(--eos-hairline)" }}>
        <EosSegmentedControl label="Routines" defaultValue="installed" />
      </EosTheme>
      <EosTheme mode="dark" style={{ padding: 28, borderRadius: 24 }}>
        <EosSegmentedControl
          label="Sidebar view"
          segments={[
            { value: "home", label: "Home" },
            { value: "activity", label: "Activity" },
            { value: "starred", label: "Starred" },
          ]}
        />
      </EosTheme>
    </div>
  );
}

