"use client";
/**
 * EosSegmentedControl: a radiogroup on a track, with the chosen segment raised on a thumb that slides between
 * options. Arrow keys, Home and End move the choice; only the chosen segment is in the tab order.
 *
 * The thumb is the shared Eos indicator (motion.ts): it slides and stretches to the choice with FLIP, its rounded ends
 * kept round, while the chosen label's stronger ink fades in. Before it is placed (on the server, before hydration)
 * the chosen segment paints itself.
 */
import { useRef, type CSSProperties, type KeyboardEvent, type ReactNode } from "react";
import { EosIndicator, useEosIndicator } from "./motion";
import { cx, rovingIndex, useControlled } from "./shared";
import { EosScope, useEosTheme } from "./theme";

export interface EosSegment {
  value: string;
  label: string;
  icon?: ReactNode;
}

const CSS = `
.eos-seg{position:relative;display:inline-grid;grid-auto-flow:column;grid-auto-columns:auto;gap:2px;padding:3px;border-radius:calc(var(--eos-seg-h) / 2.6 + 3px);background:var(--eos-seg-track);font-family:var(--eos-font-body);box-sizing:border-box;isolation:isolate}
.eos-seg[data-block=true]{display:grid;grid-auto-columns:1fr;width:100%}
.eos-seg>.eos-ind{--eos-ind-fill:var(--eos-seg-active);--eos-ind-ring:var(--eos-hairline-strong);transition:transform var(--eos-dur-press) var(--eos-ease)}
.eos-seg-option{position:relative;z-index:1;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:var(--eos-seg-h);padding:0 var(--eos-seg-pad);border:0;border-radius:calc(var(--eos-seg-h) / 2.6);background:transparent;color:var(--eos-text-secondary);font:inherit;font-size:var(--eos-seg-font);font-weight:450;white-space:nowrap;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform var(--eos-dur-press) var(--eos-ease)}
.eos-seg-option[aria-checked=true] .eos-seg-i{color:var(--eos-text)}
.eos-seg-i{display:inline-grid;place-items:center}
.eos-seg-t{position:relative}
.eos-seg-t::after{content:attr(data-text);content:attr(data-text) / "";position:absolute;left:0;top:0;color:var(--eos-text);opacity:0;pointer-events:none;white-space:nowrap;transition:opacity var(--eos-dur-indicator) var(--eos-ease)}
.eos-seg-option[aria-checked=true] .eos-seg-t::after{opacity:1}
@media (hover:hover){.eos-seg-option:hover .eos-seg-t::after{opacity:1;transition-duration:var(--eos-dur-hover)}}
.eos-seg-option:active,.eos-seg:has(>.eos-seg-option[aria-checked=true]:active)>.eos-ind{transform:scale(var(--eos-press))}
.eos-seg:not([data-eos-ind=on])>.eos-seg-option[aria-checked=true]{background:var(--eos-seg-active);box-shadow:0 0 0 1px var(--eos-hairline-strong)}
.eos-seg-option:focus-visible{outline:2px solid var(--eos-focus);outline-offset:1px}
`;

const SIZES = { sm: { h: 30, pad: 14, font: 14 }, md: { h: 36, pad: 18, font: 15.5 } } as const;

export const EOS_SEGMENT_DEFAULTS: readonly EosSegment[] = [
  { value: "installed", label: "Installed" },
  { value: "discover", label: "Discover" },
];

export interface EosSegmentedControlProps {
  segments?: readonly EosSegment[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  /** The group's accessible name. */
  label?: string;
  /** Stretch to the width of its container, with equal segments. */
  block?: boolean;
  size?: keyof typeof SIZES;
  className?: string;
  style?: CSSProperties;
}

export function EosSegmentedControl({
  segments = EOS_SEGMENT_DEFAULTS,
  value,
  defaultValue,
  onChange,
  label = "View",
  block = false,
  size = "md",
  className,
  style,
}: EosSegmentedControlProps) {
  const [current, setCurrent] = useControlled(value, defaultValue ?? segments[0]?.value ?? "", onChange);
  const chosen = Math.max(
    0,
    segments.findIndex((segment) => segment.value === current),
  );
  const track = useRef<HTMLDivElement>(null);
  const options = useRef<(HTMLButtonElement | null)[]>([]);
  const thumb = useRef<HTMLSpanElement>(null);
  const scope = useEosTheme();
  // A translucent thumb (glass in the dark) keeps its parts edge to edge; an opaque one tucks the middle under its ends.
  const opaque = !(scope?.look === "glass" && scope.mode === "dark");
  useEosIndicator({ host: track, indicator: thumb, target: () => options.current[chosen], choice: `${chosen}:${segments.length}`, ring: 1, opaque, look: scope?.look });

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = rovingIndex(event.key, index, segments.length);
    if (next < 0) return;
    event.preventDefault();
    const segment = segments[next];
    if (!segment) return;
    setCurrent(segment.value);
    options.current[next]?.focus();
  };
  const s = SIZES[size];
  const vars = { "--eos-seg-h": `${s.h}px`, "--eos-seg-pad": `${s.pad}px`, "--eos-seg-font": `${s.font}px` } as CSSProperties;

  return (
    <EosScope>
      <style>{CSS}</style>
      <div
        ref={track}
        role="radiogroup"
        aria-label={label}
        className={cx("eos-seg", className)}
        data-block={block}
        style={{ ...vars, ...style }}
      >
        <EosIndicator ref={thumb} className="eos-seg-thumb" />
        {segments.map((segment, index) => {
          const on = index === chosen;
          return (
            <button
              key={segment.value}
              ref={(el) => {
                options.current[index] = el;
              }}
              type="button"
              role="radio"
              aria-checked={on}
              tabIndex={on ? 0 : -1}
              className="eos-seg-option"
              onClick={() => setCurrent(segment.value)}
              onKeyDown={(event) => onKeyDown(event, index)}
            >
              {segment.icon && <span className="eos-seg-i">{segment.icon}</span>}
              <span className="eos-seg-t" data-text={segment.label}>
                {segment.label}
              </span>
            </button>
          );
        })}
      </div>
    </EosScope>
  );
}
